// @scena/scenes: built-in scenes and sample pages, as JSON plus typed exports.
// desk.scene.json is generated by scripts/encode-desk.ts (the hand-encoding of the
// original prototype); edit the encoder, then run `pnpm encode:desk`.
// samples.json holds extra sample drawings (scripts/encode-samples.ts): the steaming mug.

import type { ArtLayer, Asset, ObjectLayer, PageDocument, SceneDocument, Slot } from "@scena/scene";
import desk from "../desk.scene.json" with { type: "json" };
import pia from "../pia.page.json" with { type: "json" };
import samples from "../samples.json" with { type: "json" };

export const DESK_SCENE: SceneDocument = desk as unknown as SceneDocument;
export const PIA_PAGE: PageDocument = pia as unknown as PageDocument;

/** A drawing offered on its own: its layer as it sits on a desk, its link slot and its assets. */
export interface SampleDrawing {
  key: string;
  name: string;
  layer: ObjectLayer;
  slot: Slot;
  assets: Record<string, Asset>;
}

/** The steaming mug: three frames of rising steam over a still colour layer (ADR 0002). */
export const MUG_SAMPLE: SampleDrawing = (samples as unknown as Record<string, SampleDrawing>).mug!;

/** A background offered on its own (ADR 0003): its layer, fitted and clipped, and its assets. */
export interface SampleBackground {
  key: string;
  name: string;
  layer: ArtLayer;
  assets: Record<string, Asset>;
}
/** The drawn desk top: plank seams and a wash of colour, painted to recolour with any palette. */
export const BACKGROUND_SAMPLES: SampleBackground[] = Object.values((samples as unknown as { backgrounds: Record<string, SampleBackground> }).backgrounds);

const clone = <T>(o: T): T => JSON.parse(JSON.stringify(o));

/**
 * Pia's desk with the steaming mug on its coffee ring, as a clickable tip link: the frames
 * demo (dist/demo-frames.html) and the page the runtime and performance checks use.
 */
export function framesDemo(): { scene: SceneDocument; page: PageDocument } {
  const scene = clone(DESK_SCENE), page = clone(PIA_PAGE);
  const m = clone(MUG_SAMPLE);
  Object.assign(scene.assets, m.assets);
  scene.layers.push(m.layer);
  scene.slots.push(m.slot);
  scene.fallback.order.push(m.slot.id);
  page.links[m.slot.id] = { enabled: true, title: m.slot.defaults.title, description: m.slot.defaults.description, cta: m.slot.defaults.cta, url: "https://ko-fi.com/piamorandi" };
  return { scene, page };
}
